{
  "name": "@usepipa/pipa",
  "version": "0.6.1",
  "description": "Run Pipa through Slack Socket Mode with OpenCode",
  "keywords": [
    "slack",
    "opencode",
    "ai-agent",
    "cli"
  ],
  "type": "module",
  "bin": {
    "pipa": "bin/pipa.mjs"
  },
  "files": [
    "bin",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test",
    "test:pack": "node scripts/pack-smoke.mjs",
    "test:engines": "node scripts/test-opencode-matrix.mjs",
    "test:beta": "node scripts/test-opencode-matrix.mjs --smoke",
    "test:slack:routines": "node scripts/slack-routine-eval.mjs",
    "test:slack:release": "node scripts/slack-release-eval.mjs"
  },
  "engines": {
    "node": ">=22"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lunchpaillola/pipa.git"
  },
  "homepage": "https://github.com/lunchpaillola/pipa#readme",
  "bugs": {
    "url": "https://github.com/lunchpaillola/pipa/issues"
  },
  "author": "Lunch Pail Labs",
  "license": "Apache-2.0",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@chat-adapter/slack": "4.38.1",
    "@chat-adapter/state-memory": "4.38.1",
    "@opencode/client": "2.0.29",
    "chat": "4.38.1",
    "cross-spawn": "7.0.6",
    "luxon": "3.7.2"
  }
}

#!/usr/bin/env node

import crossSpawn from "cross-spawn";
import { constants } from "node:fs";
import { open, readFile, realpath, stat } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import path from "node:path";
import os from "node:os";
import { createInterface } from "node:readline/promises";
import { Writable } from "node:stream";
import { stdin, stdout } from "node:process";
import { acquireInstanceLock, createManifest, createManifestUrl, loadConfig, stopInstance } from "../src/state.mjs";
import { initializePipa, startPipa } from "../src/app.mjs";
import { PipaRestartingError, startOpenCodeServer } from "../src/opencode.mjs";
import { createRoutine, deleteRoutine, editRoutine, loadRoutineState, requestRoutineRun } from "../src/routines.mjs";
import { requestRestart, restartStatus, startRestartWatcher, reportRestartReady, reportRestartFailure } from "../src/restart.mjs";

const packageJson = JSON.parse(await readFile(new URL("../package.json", import.meta.url), "utf8"));

async function main(argv = process.argv.slice(2), io = { input: stdin, output: stdout }) {
  const command = argv[0];
  if (command === "--version" || command === "-v") {
    io.output.write(`${packageJson.version}\n`);
    return;
  }
  if (command === "init") return init(io);
  if (command === "start") return start(io);
  if (command === "stop") return stop(io);
  if (command === "restart") return restart(argv.slice(1), io);
  if (command === "routine") return routine(argv.slice(1), io);
  if (command === "manifest") return manifest(argv.slice(1), io);
  const usage = "Usage: pipa init | pipa start | pipa stop | pipa restart [--status] | pipa routine | pipa manifest | pipa --version";
  if (command === "--help" || command === "-h") return io.output.write(`${usage}\n`);
  throw new Error(usage);
}

async function manifest(argv, io) {
  const usage = "Usage: pipa manifest\nPrint the current local Slack manifest template from the existing profile without credentials. This does not update Slack or local state.\n";
  if (argv.length === 1 && ["--help", "-h"].includes(argv[0])) return io.output.write(usage);
  if (argv.length) throw new Error(usage.trim());
  const config = await loadConfig();
  io.output.write(`${JSON.stringify(createManifest(config.botName), null, 2)}\n`);
}

async function restart(argv, io) {
  if (argv.length === 1 && ["--help", "-h"].includes(argv[0])) {
    io.output.write("Usage: pipa restart [--status] [--channel <id> [--thread <ts>]]\nRequest a detached restart, or inspect its latest durable outcome.\n");
    return;
  }
  if (argv[0] === "--status") {
    if (argv.length !== 1) throw new Error("Usage: pipa restart [--status] [--channel <id> [--thread <ts>]]");
    const status = await restartStatus();
    io.output.write(status ? `${JSON.stringify(status, null, 2)}\n` : "No restart requested.\n");
    return;
  }
  let channelId;
  let threadTs;
  for (let index = 0; index < argv.length; index += 2) {
    if (argv[index] === "--channel" && argv[index + 1]) channelId = argv[index + 1];
    else if (argv[index] === "--thread" && argv[index + 1]) threadTs = argv[index + 1];
    else throw new Error("Usage: pipa restart [--status] [--channel <id> [--thread <ts>]]");
  }
  if (threadTs && !channelId) throw new Error("Usage: pipa restart [--status] [--channel <id> [--thread <ts>]]");
  const request = await requestRestart({ destination: channelId ? { channelId, ...(threadTs ? { threadTs } : {}) } : undefined });
  io.output.write(`Restart requested (${request.id}). Check \`pipa restart --status\` for the outcome.\n`);
}

const ROUTINE_HELP = `Usage: pipa routine <command>

Commands:
  create (--prompt <text> | --prompt-file <path>) --timezone <iana> --channel <id> [--thread <ts>] <schedule> [--preview] [--json]
  list [--json]
  show <id> [--json]
  edit <id> [--prompt <text> | --prompt-file <path>] [--timezone <iana>] [--channel <id>] [--thread <ts|none>] [<schedule>] [--status active|inactive] [--json]
  run <id> [--json]
  delete <id> [--json]

Schedules: --at <iso> | --in <positive><m|h|d|w> | --every <positive><m|h|d|w>
Recurring options: --times <HH:MM,...> --weekdays <1,...,7> --until <YYYY-MM-DD>

Timezone must be an IANA name such as America/New_York or UTC. Pipa does not
interpret aliases such as EST. --until is an inclusive local date. Use
--prompt-file for exact multiline prompts or prompts containing shell syntax.

Examples:
  pipa routine create --prompt "Daily brief" --timezone America/New_York --channel C123 --every 1d --times 05:00 --preview --json
  pipa routine create --prompt "Check queue" --timezone UTC --channel C123 --every 30m --preview --json
  pipa routine create --prompt "Follow up" --timezone UTC --channel C123 --in 5m --preview --json
  pipa routine create --prompt "Status" --timezone America/New_York --channel C123 --every 1w --weekdays 2,4,6 --times 09:00,15:00,18:00 --preview --json
  pipa routine create --prompt "Evening close" --timezone America/New_York --channel C123 --every 1d --times 19:00 --until 2030-09-05 --preview --json

--preview validates and normalizes without writing routines.json. Agents should
preview, show the normalized JSON, and create only after user confirmation.
JSON success output includes ok plus routine, routines, or deleted. JSON errors
include ok:false and a stable error object.

Routines use normal local OpenCode authority and run only while the Socket Mode
pipa start process is running and this machine is awake. Restart skips missed
scheduled work; an explicit run request remains pending and can repeat if the
process crashes after external side effects but before saving completion.
Completed routines remain visible until deleted. run never changes the saved
schedule or lifecycle status. Managed profiles do not execute routines.
`;

async function routine(argv, io) {
  const command = argv[0];
  if (!command || command === "--help" || command === "-h") {
    io.output.write(ROUTINE_HELP);
    return;
  }
  const { values, positionals } = parseRoutineArgs(argv.slice(1));
  const json = values.json === true;

  if (command === "list") {
    requireNoOptions(values, ["json"]);
    if (positionals.length) cliError("list does not accept an ID");
    const routines = (await loadRoutineState()).routines;
    return writeRoutineResult(io.output, json, { routines }, routines.length
      ? routines.map((item) => `${item.id}\t${item.status}\t${item.nextRunAt ?? "-"}`).join("\n")
      : "No routines.");
  }
  if (command === "show") {
    requireNoOptions(values, ["json"]);
    const id = requireId(positionals);
    const found = (await loadRoutineState()).routines.find((item) => item.id === id);
    if (!found) cliError(`Routine not found: ${id}`, "not_found");
    return writeRoutineResult(io.output, json, { routine: found }, formatRoutine(found));
  }
  if (command === "run") {
    requireNoOptions(values, ["json"]);
    const id = requireId(positionals);
    const requested = await requestRoutineRun(id);
    return writeRoutineResult(io.output, json, { routine: requested }, `Run requested for ${id}.`);
  }
  if (command === "delete") {
    requireNoOptions(values, ["json"]);
    const id = requireId(positionals);
    await deleteRoutine(id);
    return writeRoutineResult(io.output, json, { deleted: id }, `Deleted routine ${id}.`);
  }
  if (command !== "create" && command !== "edit") cliError(`Unknown routine command: ${command}`);

  const id = command === "edit" ? requireId(positionals) : positionals.length === 0 ? randomUUID() : cliError("create does not accept an ID");
  const config = await loadConfig();
  const now = new Date().toISOString();
  const changes = await routineInput(values, command === "create", now, config.workingDirectory);
  const options = { now, allowedChannelIds: config.allowedSlackChannelIds ?? [] };
  const result = command === "create"
    ? await createRoutine({ id, ...changes, model: config.defaultModel ?? null }, { ...options, preview: values.preview === true })
    : await editRoutine(id, changes, options);
  const preview = command === "create" && values.preview === true;
  return writeRoutineResult(io.output, json, { routine: result, ...(preview ? { preview: true } : {}) }, preview
    ? `Preview: ${formatRoutine(result)}`
    : `${command === "create" ? "Created" : "Edited"} routine ${id}.`);
}

function parseRoutineArgs(argv) {
  const booleanOptions = new Set(["json", "preview"]);
  const values = {};
  const positionals = [];
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (!argument.startsWith("--")) {
      positionals.push(argument);
      continue;
    }
    const name = argument.slice(2);
    if (!name) cliError("invalid option");
    if (Object.hasOwn(values, name)) cliError(`option --${name} may only be used once`);
    if (booleanOptions.has(name)) values[name] = true;
    else {
      if (index + 1 >= argv.length) cliError(`option --${name} requires a value`);
      values[name] = argv[index += 1];
    }
  }
  return { values, positionals };
}

async function routineInput(values, creating, now, workingDirectory) {
  const supported = ["prompt", "prompt-file", "timezone", "channel", "thread", "at", "in", "every", "times", "weekdays", "until", "status", "preview", "json"];
  requireNoOptions(values, supported);
  if (!creating && values.preview) cliError("--preview is only supported by create");
  if (creating && values.status !== undefined) cliError("--status is only supported by edit");
  if (values.prompt !== undefined && values["prompt-file"] !== undefined) cliError("use exactly one of --prompt or --prompt-file");
  const changes = {};
  if (values.prompt !== undefined) changes.prompt = values.prompt;
  if (values["prompt-file"] !== undefined) changes.prompt = await readPromptFile(values["prompt-file"], workingDirectory);
  if (creating && changes.prompt === undefined) cliError("create requires --prompt or --prompt-file");
  if (values.timezone !== undefined) changes.timezone = values.timezone;
  if (creating && changes.timezone === undefined) cliError("create requires --timezone");
  if (values.channel !== undefined || values.thread !== undefined) {
    if (creating && values.channel === undefined) cliError("create requires --channel");
    changes.destination = {
      ...(values.channel === undefined ? {} : { channelId: values.channel }),
      ...(values.thread === undefined ? {} : { threadTs: values.thread === "none" ? null : values.thread }),
    };
  }
  if (creating && changes.destination === undefined) cliError("create requires --channel");
  const schedules = ["at", "in", "every"].filter((name) => values[name] !== undefined);
  if (schedules.length > 1) cliError("use exactly one of --at, --in, or --every");
  if (creating && schedules.length !== 1) cliError("create requires exactly one schedule");
  if (schedules.length === 0 && (values.times !== undefined || values.weekdays !== undefined || values.until !== undefined)) {
    cliError("--times, --weekdays, and --until require --every");
  }
  if (schedules.length === 1) changes.schedule = scheduleFromOptions(values, now);
  if (values.status !== undefined) {
    if (values.status !== "active" && values.status !== "inactive") cliError("--status must be active or inactive");
    changes.status = values.status;
  }
  return changes;
}

async function readPromptFile(file, workingDirectory) {
  const maxBytes = 1024 * 1024;
  const root = await realpath(workingDirectory);
  const requested = path.resolve(root, file);
  const initial = await stat(requested, { bigint: true });
  if (!initial.isFile()) cliError("--prompt-file must be a regular file");
  const handle = await open(requested, constants.O_RDONLY | (constants.O_NONBLOCK ?? 0));
  try {
    const opened = await handle.stat({ bigint: true });
    const current = await stat(requested, { bigint: true });
    if (!opened.isFile()
      || initial.dev !== opened.dev || initial.ino !== opened.ino
      || current.dev !== opened.dev || current.ino !== opened.ino) cliError("--prompt-file must be an unchanged regular file");
    if (opened.size > BigInt(maxBytes)) cliError("--prompt-file must be no larger than 1 MB");
    const data = Buffer.alloc(maxBytes + 1);
    let bytesRead = 0;
    while (bytesRead < data.length) {
      const read = await handle.read(data, bytesRead, data.length - bytesRead, bytesRead);
      if (!read.bytesRead) break;
      bytesRead += read.bytesRead;
    }
    if (bytesRead > maxBytes) cliError("--prompt-file must be no larger than 1 MB");
    const after = await handle.stat({ bigint: true });
    if (BigInt(bytesRead) !== opened.size || after.size !== opened.size || after.mtimeNs !== opened.mtimeNs || after.ctimeNs !== opened.ctimeNs) {
      cliError("--prompt-file changed while being read");
    }
    return data.subarray(0, bytesRead).toString("utf8");
  } finally {
    await handle.close();
  }
}

function scheduleFromOptions(values, now) {
  if (values.at !== undefined) {
    rejectRecurringOptions(values);
    return { type: "once", at: values.at };
  }
  if (values.in !== undefined) {
    rejectRecurringOptions(values);
    return { type: "once", at: new Date(Date.parse(now) + parseDuration(values.in)).toISOString() };
  }
  const match = /^(\d+)([mhdw])$/u.exec(values.every ?? "");
  if (!match || Number(match[1]) <= 0) cliError("--every must be a positive duration such as 30m, 2h, 1d, or 1w");
  const frequency = { m: "minutes", h: "hours", d: "daily", w: "weekly" }[match[2]];
  return {
    type: "recurring",
    frequency,
    interval: Number(match[1]),
    times: values.times === undefined ? [] : values.times.split(","),
    weekdays: values.weekdays === undefined ? [] : values.weekdays.split(",").map(Number),
    until: values.until ?? null,
  };
}

function parseDuration(value) {
  const match = /^(\d+)([mhdw])$/u.exec(value);
  if (!match || Number(match[1]) <= 0) cliError("--in must be a positive duration such as 5m");
  const milliseconds = { m: 60_000, h: 3_600_000, d: 86_400_000, w: 604_800_000 }[match[2]];
  return Number(match[1]) * milliseconds;
}

function rejectRecurringOptions(values) {
  if (values.times !== undefined || values.weekdays !== undefined || values.until !== undefined) cliError("--times, --weekdays, and --until require --every");
}

function requireNoOptions(values, supported) {
  const unsupported = Object.keys(values).find((name) => !supported.includes(name));
  if (unsupported) cliError(`unknown option --${unsupported}`);
}

function requireId(positionals) {
  if (positionals.length !== 1) cliError("command requires exactly one routine ID");
  return positionals[0];
}

function writeRoutineResult(output, json, value, human) {
  output.write(json ? `${JSON.stringify({ ok: true, ...value })}\n` : `${human}\n`);
}

function formatRoutine(routine) {
  return `${routine.id}\nStatus: ${routine.status}\nNext run: ${routine.nextRunAt ?? "-"}\nDestination: ${routine.destination.channelId}${routine.destination.threadTs ? ` thread ${routine.destination.threadTs}` : ""}`;
}

function cliError(message, code = "invalid_arguments") {
  const error = new Error(message);
  error.code = code;
  throw error;
}

async function stop(io) {
  const pid = await stopInstance();
  io.output.write(pid ? `Pipa is stopping (PID ${pid}).\n` : "Pipa is not running.\n");
}

async function init(io) {
  let muted = false;
  const promptOutput = new Writable({
    write(chunk, encoding, callback) {
      if (!muted) io.output.write(chunk, encoding);
      callback();
    },
  });
  const prompt = createInterface({ input: io.input, output: promptOutput, terminal: Boolean(io.input.isTTY) });
  try {
    const botName = process.env.PIPA_BOT_NAME?.trim()
      || (await prompt.question("What should we call your bot? (leave empty to use Pipa; you can change this later): ")).trim()
      || "Pipa";
    const hasSlackTokens = process.env.PIPA_SLACK_APP_TOKEN && process.env.PIPA_SLACK_BOT_TOKEN;
    const workingDirectory = process.cwd();
    if (!hasSlackTokens) {
      io.output.write(`\nPipa will work in this folder:\n\n  ${workingDirectory}\n\nPeople in Slack channels where you add ${botName} can ask it to read and change files in this folder.\n\n`);
      if (!await confirm(prompt, io.output)) {
        io.output.write("\nSetup cancelled. Change into the folder where you want Pipa to work, then run `pipa init` again.\n");
        return;
      }
    }
    if (!hasSlackTokens) {
      const manifestUrl = createManifestUrl(createManifest(botName));
      io.output.write("\nOpening Slack with your app configuration...\n");
      if (io.input.isTTY) await openUrl(manifestUrl).catch(() => undefined);
      io.output.write(`\nIf Slack did not open, use this link:\n${manifestUrl}\n\n`);
      io.output.write("In Slack:\n1. Choose your workspace, review the configuration, and create the app.\n2. Under Basic Information, generate an app-level token with connections:write.\n3. Under OAuth & Permissions, install the app and copy its Bot User OAuth Token.\n\n");
    }
    const askSecret = async (question, label) => {
      io.output.write(question);
      muted = true;
      const value = await prompt.question("");
      muted = false;
      io.output.write(`\n✓ ${label} received.\n`);
      return value;
    };
    const slackAppToken = process.env.PIPA_SLACK_APP_TOKEN || await askSecret("Slack app token (xapp-, input hidden): ", "App token");
    const slackBotToken = process.env.PIPA_SLACK_BOT_TOKEN || await askSecret("Slack bot token (xoxb-, input hidden): ", "Bot token");
    const allowedSlackChannelIds = process.env.PIPA_ALLOWED_CHANNEL_IDS
      ?? (await prompt.question("Allowed Slack channel IDs (comma-separated, e.g. C0BSE2JTYPR; leave empty to allow any channel): ")).trim();
    const allowedSlackUserIds = process.env.PIPA_ALLOWED_USER_IDS
      ?? (await prompt.question("Allowed Slack user IDs (comma-separated, e.g. UFWBSCZ54; leave empty to allow any user): ")).trim();
    const allowedSlackBotIds = process.env.PIPA_ALLOWED_BOT_IDS
      ?? (await prompt.question("Allowed Slack bot IDs (comma-separated, e.g. B0C6Q27E82X; leave empty to ignore bot messages): ")).trim();
    const mentionOnly = process.env.PIPA_MENTION_ONLY !== undefined
      ? /^(1|true|yes)$/iu.test(process.env.PIPA_MENTION_ONLY.trim())
      : /^y(es)?$/iu.test((await prompt.question("Only respond when @-mentioned, even in threads Pipa is already in? [y/N]: ")).trim());
    io.output.write("\nChecking OpenCode and Slack credentials...\n");
    const result = await initializePipa({ botName, workingDirectory, slackAppToken, slackBotToken, allowedSlackChannelIds, allowedSlackUserIds, allowedSlackBotIds, mentionOnly });
    io.output.write(`✓ Credentials validated.\n\nSaved config to ${result.paths.config}. Run \`pipa start\`.\n`);
  } finally {
    prompt.close();
  }
}

async function confirm(prompt, output) {
  while (true) {
    const answer = (await prompt.question("Continue? [Y/n]: ")).trim().toLowerCase();
    if (!answer || answer === "y" || answer === "yes") return true;
    if (answer === "n" || answer === "no") return false;
    output.write("Please answer y or n.\n");
  }
}

function openUrl(url) {
  let command = "xdg-open";
  let args = [url];
  if (process.platform === "darwin") command = "open";
  if (process.platform === "win32") {
    command = "rundll32";
    args = ["url.dll,FileProtocolHandler", url];
  }
  return new Promise((resolve, reject) => {
    const child = crossSpawn(command, args, { detached: true, stdio: "ignore" });
    child.once("spawn", () => {
      child.unref();
      resolve();
    });
    child.once("error", reject);
  });
}

async function start(io) {
  // Resolve before OpenCode changes cwd, so its tools address this same profile.
  process.env.PIPA_HOME = path.resolve(process.env.PIPA_HOME || os.homedir());
  const releaseLock = await acquireInstanceLock();
  const finished = Promise.withResolvers();
  void finished.promise.catch(() => undefined);
  const signal = Promise.withResolvers();
  const startup = new AbortController();
  let app;
  let server;
  let watcher;
  let failure;
  let stopping = false;
  let ready = false;
  const stop = (termination = "SIGTERM", reason) => {
    stopping = true;
    app?.stop(reason);
    startup.abort();
    server?.stop(termination);
    signal.resolve();
  };
  const stopWithSigint = () => stop("SIGINT");
  const stopWithSigterm = () => stop();
  const disconnected = () => {
    if (!ready) {
      failure ??= new Error("Restart readiness handoff disconnected before startup completed.");
      stop();
    }
  };
  if (process.env.PIPA_RESTART_ID) process.on("disconnect", disconnected);
  process.on("SIGINT", stopWithSigint);
  process.on("SIGTERM", stopWithSigterm);
  try {
    const config = await loadConfig();
    if (config.slackMode === "managed") {
      server = await startOpenCodeServer(config, { signal: startup.signal });
      io.output.write(`Pipa is starting OpenCode on ${config.openCodeHostname}:${config.openCodePort}.\n`);
      await Promise.race([server.ready(), signal.promise]);
    } else {
      io.output.write("Waiting for OpenCode... Ctrl+C to stop.\n");
      app = await startPipa({ config, signal: startup.signal });
      io.output.write(app.server.owned
        ? `Pipa started a private OpenCode server at ${app.server.baseUrl}.\n`
        : `Pipa is using the configured OpenCode server at ${app.server.baseUrl}.\n`);
      io.output.write("Pipa is connected through Slack Socket Mode.\n");
    }
    const lifetime = app ? app.wait() : server.wait();
    // Observe startup failures already reported by the runtime before ready IPC.
    await Promise.race([lifetime, Promise.resolve()]);
    if (!stopping) {
      watcher = startRestartWatcher({
        identity: releaseLock.identity,
        shutdown: () => { stop("SIGTERM", new PipaRestartingError()); return finished.promise; },
        onError: () => process.stderr.write("Pipa could not inspect restart requests.\n"),
      });
      await reportRestartReady(releaseLock.identity);
      ready = true;
      if (app && process.env.PIPA_RESTART_CHANNEL_ID) {
        await app.postRestartReady({
          channelId: process.env.PIPA_RESTART_CHANNEL_ID,
          ...(process.env.PIPA_RESTART_THREAD_TS ? { threadTs: process.env.PIPA_RESTART_THREAD_TS } : {}),
        }).catch(() => process.stderr.write("Pipa could not post restart readiness to Slack.\n"));
      }
    }
    await Promise.race([signal.promise, lifetime]);
  } catch (error) {
    failure = error;
  } finally {
    watcher?.stop();
    try {
      stop();
      if (app) await app.shutdown();
      if (server) await server.wait();
    } catch (error) {
      failure ??= error;
    } finally {
      try { await releaseLock(); } catch (error) { failure ??= error; }
      if (failure) finished.reject(failure);
      else finished.resolve();
      // poll returns the in-flight handoff even after stop: don't exit before IPC.
      await watcher?.poll().catch(() => { failure ??= new Error("Restart handoff failed."); });
      process.off("SIGINT", stopWithSigint);
      process.off("SIGTERM", stopWithSigterm);
      process.off("disconnect", disconnected);
    }
  }
  if (failure) throw failure;
}

main().catch(async (error) => {
  await reportRestartFailure();
